import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry (1x1 unit, texture will define aspect via material)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply rotation & scale from config (position is set by adapter)
  if (config.rotation && config.rotation.length === 3) {
    mesh.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  }
  if (config.scale && config.scale.length === 3) {
    mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);
  }

  // Load texture asynchronously; material gets updated when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Hover lift (rise‑in) timeline
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: mesh.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  // Click press‑down timeline
  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(mesh.scale, {
    x: mesh.scale.x * 0.97,
    y: mesh.scale.y * 0.97,
    z: mesh.scale.z * 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  });

  // Event handlers attached to userData
  root.userData.handlers = {
    hover: (enter) => {
      if (enter) {
        hoverTimeline.play(0);
      } else {
        hoverTimeline.reverse();
      }
    },
    click: () => {
      pressTimeline.restart();
      ctx.emit('hub-journal.select', {});
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverTimeline.kill();
    pressTimeline.kill();
    geometry.dispose();
    material.dispose();
  };

  return root;
}
